/* TRX-SD 44.1 kHz render (trxsd_render_block_44k1), hand-written SHARC+.
 * Generated by gen_trxsd.py.
 *
 * Bit-exact replacement for the native C port (tools/trxsd/trxsd.c, with
 * native_support.sd_source's shared-scratch effects, its trxsd_tonal and
 * trxsd_filter helpers), checked by native_gate.py against that C render.
 *
 *  1. Two sine oscillators: phase y18:y19 / y20:y21 (15-bit whole part, lo
 *     kept << 8 so the add carries), step 2^19 * (y7 + 2*y16) / (y8 + ...),
 *     amplitudes y3 / y4.
 *  2. y16 (pitch envelope: +2*y10 while y17 <= y13, then *y12), y29 (clip
 *     envelope, *y9).
 *  3. Tonal: x = lim(floor(L*S / 2^17) + S), S = tone + osc2, L = old y29;
 *     tone = 2*x*e / 2^24, e = y14 *= y1 (no limit, as trxsd_tonal).
 *  4. Fibonacci noise (y23, y24) through two identical resonators (states
 *     y25..y28); coefficients from the cos/radius tables at
 *     y11; then *y15 (decay y2).
 *  5. out = lim(2*n*y6 + tone), plus 2*T*y5 from the transient table while
 *     y17 <= $fe0.
 *
 * Declines (calls the C render) when an oscillator phase is outside
 * [0, $7fff] or y11 is outside the coefficient tables.
 *
 * Calling convention: R4 = voice, R8 = sine (signed 24-bit words).
 * @TMP@ = a 256-word scratch block owned by the hand-written renders.
 */
.EXTERN trxsd_tables_hw.;
.EXTERN md_shared_scratch_x.;
.EXTERN md_shared_scratch_y.;
.EXTERN md_shared_y20.;
.EXTERN trxsd_render_block_44k1_c.;
.SECTION/SW seg_swco;
.GLOBAL trxsd_render_block_44k1.;
trxsd_render_block_44k1.:
    I7=MODIFY (I7,-0x34)(NW);
    DM (-3,I6) = R8;
    DM (-4,I6) = R9;
    DM (-5,I6) = R10;
    DM (-6,I6) = R11;
    DM (-7,I6) = R12;
    DM (-8,I6) = R13;
    DM (-9,I6) = R14;
    DM (-10,I6) = R15;
    R0 = I0;
    DM (-11,I6) = R0;
    R0 = I1;
    DM (-12,I6) = R0;
    R0 = I2;
    DM (-13,I6) = R0;
    R0 = I3;
    DM (-14,I6) = R0;
    R0 = I4;
    DM (-15,I6) = R0;
    R0 = I5;
    DM (-16,I6) = R0;
    R0 = M4;
    DM (-17,I6) = R0;
    R0 = M0;
    DM (-18,I6) = R0;
    R0 = M1;
    DM (-19,I6) = R0;
    R0 = M2;
    DM (-20,I6) = R0;
    R0 = M3;
    DM (-21,I6) = R0;
    R0 = MR0F;
    DM (-22,I6) = R0;
    R0 = MR1F;
    DM (-23,I6) = R0;
    R0 = MR2F;
    DM (-24,I6) = R0;
    DM (-28,I6) = R8;
    R0 = L0;
    DM (-46,I6) = R0;
    R0 = L1;
    DM (-47,I6) = R0;
    R0 = L2;
    DM (-48,I6) = R0;
    R0 = L3;
    DM (-49,I6) = R0;
    R0 = L4;
    DM (-50,I6) = R0;
    R0 = L5;
    DM (-51,I6) = R0;
    R0 = 0;
    L0 = R0;
    L1 = R0;
    L2 = R0;
    L3 = R0;
    L4 = R0;
    L5 = R0;
    I0 = R4;
    R14 = 0x7FFFFF;
    R15 = 0xFF800000;
    R13 = @SRC@;
/* ---- guards ---------------------------------------------------------------- */
    R0 = I0;
    DM (-40,I6) = R0;                   /* voice */
    R1 = 0x8000;
    R0 = DM (18,I0);
    COMPU (R0,R1);
    IF GE JUMP .L_decline;
    R0 = DM (20,I0);
    COMPU (R0,R1);
    IF GE JUMP .L_decline;
    R0 = DM (11,I0);
    R1 = 1024;
    R0 = R0 - R1;
    R1 = 509;
    COMPU (R0,R1);
    IF GE JUMP .L_decline;
    R12 = -8;
    R0 = DM (-28,I6);
    I4 = R0;                            /* sine */
    R6 = 0x7FFF;
    R13 = -5;
    R0 = DM (16,I0);
    R7 = R0 + R0;                       /* 2*y16 */
/* ---- oscillator 1 -------------------------------------------------------- */
    R0 = DM (7,I0);
    R0 = R0 + R7;                       /* T = y7 + 2*y16: step = T * 2^19 */
    R3 = ASHIFT R0 BY R13;
    R4 = LSHIFT R0 BY 27;
    R1 = DM (18,I0);
    R2 = DM (19,I0);
    R2 = LSHIFT R2 BY 8;
    R5 = DM (3,I0);
    I1 = @TMP@;
    LCNTR = 0x20 , DO (PC,.L_osc0_end)UNTIL LCE;
    M4 = R1;
    R2 = R2 + R4;
    R1 = R1 + R3 + CI;
    R1 = R1 AND R6;
    R0 = DM (M4,I4);
    R0 = LSHIFT R0 BY 8;
    R0 = R0 * R5 (SSF);
.L_osc0_end:
    DM (I1,M6) = R0;
    DM (18,I0) = R1;
    R2 = ASHIFT R2 BY R12;
    DM (19,I0) = R2;
/* ---- oscillator 2 -------------------------------------------------------- */
    R0 = DM (8,I0);
    R0 = R0 + R7;                       /* T = y7 + 2*y16: step = T * 2^19 */
    R3 = ASHIFT R0 BY R13;
    R4 = LSHIFT R0 BY 27;
    R1 = DM (20,I0);
    R2 = DM (21,I0);
    R2 = LSHIFT R2 BY 8;
    R5 = DM (4,I0);
    I1 = @TMP@;
    I1=MODIFY (I1,0x20)(NW);
    LCNTR = 0x20 , DO (PC,.L_osc1_end)UNTIL LCE;
    M4 = R1;
    R2 = R2 + R4;
    R1 = R1 + R3 + CI;
    R1 = R1 AND R6;
    R0 = DM (M4,I4);
    R0 = LSHIFT R0 BY 8;
    R0 = R0 * R5 (SSF);
.L_osc1_end:
    DM (I1,M6) = R0;
    DM (20,I0) = R1;
    R2 = ASHIFT R2 BY R12;
    DM (21,I0) = R2;
/* ---- y16, y29 ------------------------------------------------------------- */
    R0 = DM (17,I0);
    R1 = DM (13,I0);
    R2 = DM (16,I0);
    COMP (R0,R1);
    IF GT JUMP .L_y16_decay;
    R0 = DM (10,I0);
    R0 = R0 + R0;
    R2 = R2 + R0;
    JUMP .L_y16_st;
.L_y16_decay:
    R0 = DM (12,I0);
    R0 = LSHIFT R0 BY 8;
    R2 = R2 * R0 (SSF);
.L_y16_st:
    R2 = MIN(R2,R14);
    R2 = MAX(R2,R15);
    DM (16,I0) = R2;
    R8 = DM (29,I0);                    /* L = old clip envelope */
    R0 = DM (9,I0);
    R0 = LSHIFT R0 BY 8;
    R0 = R8 * R0 (SSF);
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
    DM (29,I0) = R0;
/* ---- tonal ---------------------------------------------------------------- */
    R8 = LSHIFT R8 BY 8;                /* L << 8 */
    R9 = DM (14,I0);                    /* e */
    R10 = DM (1,I0);
    R10 = LSHIFT R10 BY 8;
    I1 = @TMP@;
    I2 = @TMP@;
    I2=MODIFY (I2,0x20)(NW);
    LCNTR = 0x20 , DO (PC,.L_tonal_end)UNTIL LCE;
    R0 = DM (I1,M5);
    R1 = DM (I2,M6);
    R0 = R0 + R1;                       /* S */
    R1 = LSHIFT R0 BY 6;
    R1 = R8 * R1 (SSF);                 /* floor(L*S / 2^17) */
    R0 = R0 + R1;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
    R0 = LSHIFT R0 BY 8;
    R0 = R0 * R9 (SSF);
    R9 = R9 * R10 (SSF);
.L_tonal_end:
    DM (I1,M6) = R0;
    DM (14,I0) = R9;
/* ---- resonator coefficients ------------------------------------------------- */
    R0 = DM (11,I0);
    R1 = 1024;
    R0 = R0 - R1;
    M4 = R0;
    R1 = trxsd_tables_hw.;
    I3 = R1;
    R1 = DM (0,I3);
    I5 = R1;
    R2 = DM (M4,I5);                    /* c */
    R1 = DM (1,I3);
    I5 = R1;
    R3 = DM (M4,I5);                    /* d */
    R2 = LSHIFT R2 BY 8;
    R2 = ASHIFT R2 BY R12;
    R3 = LSHIFT R3 BY 8;                /* d << 8 */
    R0 = ASHIFT R3 BY R12;
    R4 = 0;
    MR1F = R4;
    MR0F = R4;                          /* MR = 0 */
    MRF = MRF - R3 * R0 (SSF);
    R4 = MR1F;
    R4 = MIN(R4,R14);
    R4 = MAX(R4,R15);                   /* fb2 = lim(floor(-2*d*d / 2^24)) */
    R0 = R2 + R2;
    R5 = R3 * R0 (SSF);
    R5 = MIN(R5,R14);
    R5 = MAX(R5,R15);                   /* fb1 = lim(floor(4*d*c / 2^24)) */
    R0 = -R0;
    R0 = R3 * R0 (SSF);
    R1 = 0x400000;
    R0 = R0 + R1;
    R0 = R0 - R4;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);                   /* feed */
    I5 = md_shared_scratch_y.;
    DM (1,I5) = R4;
    DM (0,I5) = R0;
    R11 = LSHIFT R4 BY 8;               /* fb2 << 8 */
    R10 = LSHIFT R5 BY 8;               /* fb1 << 8 */
    R9 = LSHIFT R0 BY 8;                /* feed << 8 */
/* ---- noise through the two resonators ------------------------------------------ */
    I5 = md_shared_scratch_x.;
    R0 = DM (27,I0);
    DM (30,I5) = R0;
    R0 = DM (28,I0);
    DM (31,I5) = R0;
    R6 = DM (23,I0);
    R6 = LSHIFT R6 BY 8;
    R7 = DM (24,I0);
    R7 = LSHIFT R7 BY 8;                /* Fibonacci, top-aligned */
    R1 = DM (25,I0);
    R2 = DM (26,I0);
    R3 = DM (27,I0);
    R4 = DM (28,I0);
    I1 = @TMP@;
    I1=MODIFY (I1,0x20)(NW);
    LCNTR = 0x10 , DO (PC,.L_res_end)UNTIL LCE;
    R6 = R6 + R7;
    R0 = ASHIFT R6 BY R12;         /* noise */
    MRF = R11 * R1 (SSF);
    MRF = MRF + R11 * R1 (SSF);
    MRF = MRF + R10 * R2 (SSF);
    MRF = MRF + R10 * R2 (SSF);
    MRF = MRF + R9 * R0 (SSF);
    MRF = MRF + R9 * R0 (SSF);
    R1 = MR1F;
    R1 = MIN(R1,R14);
    R1 = MAX(R1,R15);
    MRF = R11 * R3 (SSF);
    MRF = MRF + R11 * R3 (SSF);
    MRF = MRF + R10 * R4 (SSF);
    MRF = MRF + R10 * R4 (SSF);
    MRF = MRF + R9 * R1 (SSF);
    MRF = MRF + R9 * R1 (SSF);
    R3 = MR1F;
    R3 = MIN(R3,R14);
    R3 = MAX(R3,R15);
    DM (I1,M6) = R3;
    R7 = R7 + R6;
    R0 = ASHIFT R7 BY R12;         /* noise */
    MRF = R11 * R2 (SSF);
    MRF = MRF + R11 * R2 (SSF);
    MRF = MRF + R10 * R1 (SSF);
    MRF = MRF + R10 * R1 (SSF);
    MRF = MRF + R9 * R0 (SSF);
    MRF = MRF + R9 * R0 (SSF);
    R2 = MR1F;
    R2 = MIN(R2,R14);
    R2 = MAX(R2,R15);
    MRF = R11 * R4 (SSF);
    MRF = MRF + R11 * R4 (SSF);
    MRF = MRF + R10 * R3 (SSF);
    MRF = MRF + R10 * R3 (SSF);
    MRF = MRF + R9 * R2 (SSF);
    MRF = MRF + R9 * R2 (SSF);
    R4 = MR1F;
    R4 = MIN(R4,R14);
    R4 = MAX(R4,R15);
    DM (I1,M6) = R4;
.L_res_end:
    NOP;
    R6 = ASHIFT R6 BY R12;
    DM (23,I0) = R6;
    R7 = ASHIFT R7 BY R12;
    DM (24,I0) = R7;
    DM (25,I0) = R1;
    DM (26,I0) = R2;
    DM (27,I0) = R3;
    DM (28,I0) = R4;
    DM (3,I5) = R1;
    DM (2,I5) = R2;
/* ---- noise level, mix, transient ------------------------------------------- */
    R1 = DM (15,I0);                    /* level */
    R2 = DM (2,I0);
    R2 = LSHIFT R2 BY 8;
    R3 = DM (6,I0);
    R4 = DM (5,I0);
    R5 = DM (17,I0);                    /* cursor */
    I1 = @TMP@;
    I1=MODIFY (I1,0x20)(NW);
    I2 = @TMP@;
    I3 = md_shared_scratch_x.;
    I3=MODIFY (I3,0x20)(NW);
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x40)(NW);
    I4 = I0;
    I4=MODIFY (I4,0x1E)(NW);
    R0 = trxsd_tables_hw.;
    I0 = R0;
    R0 = DM (2,I0);
    R6 = LSHIFT R5 BY 2;
    R0 = R0 + R6;
    I0 = R0;                            /* transient(cursor) */
    R7 = 0xFE0;
    LCNTR = 0x20 , DO (PC,.L_mix_end)UNTIL LCE;
    R0 = DM (I1,M6);
    R6 = LSHIFT R1 BY 8;
    R0 = R0 * R6 (SSF);
    R0 = MIN(R0,R14);                   /* n = lim(2*level*noise) */
    R1 = R1 * R2 (SSF);
    R1 = MIN(R1,R14);
    R6 = DM (I2,M6);
    DM (I3,M6) = R0;
    R8 = LSHIFT R0 BY 8;
    R8 = R8 * R3 (SSF);
    R8 = R8 + R6;
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);
    DM (I5,M6) = R8;
    COMPU (R5,R7);
    IF GT JUMP .L_mix_st;
    R6 = DM (I0,M6);
    R6 = LSHIFT R6 BY 8;
    R6 = R6 * R4 (SSF);
    R8 = R8 + R6;
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);
.L_mix_st:
    NOP;
.L_mix_end:
    DM (I4,M6) = R8;
    R0 = DM (-40,I6);
    I0 = R0;                            /* voice */
    DM (15,I0) = R1;
    R0 = 32;
    R5 = R5 + R0;
    R5 = MIN(R5,R14);
    R5 = MAX(R5,R15);
    DM (17,I0) = R5;
    DM (22,I0) = R8;
    JUMP .L_exit;
.L_decline:
    /* tail call: the C reference render runs in this render's place, in
     * its caller's frame (not nested under this one: the audio stack is
     * 509 words) */
    R4 = I0;
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I7=MODIFY (I7,0x34)(NW);
    JUMP trxsd_render_block_44k1_c.;
.L_exit:
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I12=DM (M7,I6);
    JUMP (M14,I12) (DB);
    RFRAME;
    NOP;
.ENDSEG;
